// === Tab: mySketch ===
//for the WccChallenge on the theme of 'arc'. --> code  by Aaron Reuland
//Fairly simple sketch- arcs using simplex noise to lerp through palettes.
//May have low framerates on slower processors.

let gs
let palettes=[
['#f1ec78','#f1ec78','#85b19f','#6d5456','#3d4f49','#3b3c41', '#3b3c41'],
['#a8adaf','#a8adaf','#718a6a','#072376','#9e6b03','#8c1108', '#8c1108'],
['#271f17', '#271f17','#014e68','#8497a8','#c5cecf','#b8ad38','#978c0e', '#978c0e'], 
['#61b2fa','#61b2fa','#8ddcff','#545d5f','#4a403c','#b48551','#1a4670','#00264e', '#00264e']
							]

let simplex, colors

function setup() {
	createCanvas(windowWidth, windowHeight);
	 let w=max(windowWidth, windowHeight)
	gs= w/4
	first=createGraphics(width, height)
	simplex= openSimplexNoise(Date.now())
  colors= random(palettes)
}

function draw(){
	clear()
let bgP= map(simplex.noise2D(frameCount/200, Date.now()/20000), -1, 1, 0, colors.length-1)
let c1= color(colors[floor(bgP)])
let c2= color(colors[floor(bgP+1)])
let between= fract(bgP)
let bg= lerpColor(c1, c2, between)
bg.setAlpha(100)
background(bg)
for(let x=gs/4; x<=width+gs; x+=gs){

	for(let y=0; y<height+gs; y+=gs){
	tile(x, y, gs*1.5, 0, first)	
	}
}

}


function tile(x, y, w, dir){
	strokeCap(PROJECT)
	noStroke()
	for(let r=w+w/10; r>=1; r-=w/40){
		let col= map(simplex.noise3D(x/10, (y+frameCount)/200, r/100), -1, 1, 0, colors.length-1)
		var c1= color(colors[floor(col)])
		var c2= color(colors[floor(col+1)])
		var between= fract(col)

		let c= lerpColor(c1, c2, between)

   fill(c)
	 push()
		translate(x, y)
		if(dir==1){
			rotate(PI/2)
		} 

		spread=PI/2.6
		arc(-w/4.4, -w/6, r, r, -spread/2, spread/2)
		arc(w/4.4, w/6, r, r, PI-spread/2, PI+spread/2)
  pop()
	}

}

